package com.example.shortener.service;

import com.example.shortener.TestProps;
import com.example.shortener.code.ShortCodeCodec;
import com.example.shortener.domain.Expiry;
import com.example.shortener.domain.ShortUrl;
import com.example.shortener.repository.ShortUrlRepository;
import com.example.shortener.validation.UrlValidator;
import io.micrometer.core.instrument.simple.SimpleMeterRegistry;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.test.util.ReflectionTestUtils;

import java.time.Clock;
import java.time.Duration;
import java.time.Instant;
import java.time.ZoneId;
import java.time.ZoneOffset;
import java.util.Optional;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * Acceptance tests for link expiry, written from the acceptance criteria (not from the implementation):
 * 410 once expiresAt is reached (inclusive), still resolving just before, no expiry = never expires,
 * expiry in the past rejected.
 */
class LinkExpiryTest {

    private static final Instant T0 = Instant.parse("2026-11-20T10:00:00Z");
    private final MutableClock clock = new MutableClock(T0);
    private final ShortUrlRepository repository = mock(ShortUrlRepository.class);
    private ShortUrlService service;

    @BeforeEach
    void setUp() {
        LinkCache cache = new LinkCache(TestProps.defaults(), new SimpleMeterRegistry());
        service = new ShortUrlService(repository, new ShortCodeCodec(0x1234), new UrlValidator("sho.rt", false), cache, clock);
        when(repository.saveAndFlush(any(ShortUrl.class))).thenAnswer(inv -> {
            ShortUrl link = inv.getArgument(0);
            ReflectionTestUtils.setField(link, "id", 100_000L);
            return link;
        });
    }

    @Test
    void expiredLinkIsGone() {
        ShortUrl link = service.create("https://example.com/sale", "summer-sale", "owner", T0.plus(Duration.ofHours(1)));
        when(repository.findByShortCode("summer-sale")).thenReturn(Optional.of(link));
        clock.set(T0.plus(Duration.ofHours(1))); // exactly at the expiry instant: expired
        assertThatThrownBy(() -> service.resolve("summer-sale")).isInstanceOf(LinkGoneException.class);
    }

    @Test
    void notYetExpiredLinkStillResolves() {
        ShortUrl link = service.create("https://example.com/sale", "spring-sale", "owner", T0.plus(Duration.ofHours(1)));
        when(repository.findByShortCode("spring-sale")).thenReturn(Optional.of(link));
        clock.set(T0.plus(Duration.ofMinutes(59)));
        assertThat(service.resolve("spring-sale").longUrl()).isEqualTo("https://example.com/sale");
    }

    @Test
    void linkWithoutExpiryNeverExpires() {
        assertThat(Expiry.isExpired(null, Instant.MAX)).isFalse();
        ShortUrl link = service.create("https://example.com/forever", "forever-link", "owner", null);
        assertThat(link.getExpiresAt()).isNull();
        assertThat(link.isExpired(T0.plus(Duration.ofDays(3650)))).isFalse();
    }

    @Test
    void rejectsExpiryInThePast() {
        assertThatThrownBy(() -> service.create("https://example.com", "too-late", "owner", T0.minusSeconds(1)))
                .isInstanceOf(BadRequestException.class)
                .hasMessageContaining("future");
        assertThatThrownBy(() -> service.create("https://example.com", "right-now", "owner", T0))
                .isInstanceOf(BadRequestException.class);
    }

    /** A clock the test can move. */
    static final class MutableClock extends Clock {
        private Instant now;

        MutableClock(Instant start) {
            this.now = start;
        }

        void set(Instant instant) {
            this.now = instant;
        }

        @Override
        public ZoneId getZone() {
            return ZoneOffset.UTC;
        }

        @Override
        public Clock withZone(ZoneId zone) {
            return this;
        }

        @Override
        public Instant instant() {
            return now;
        }
    }
}
